+uintptr_t ijk_av_dict_strtoptr(char * value) {
+    uintptr_t ptr = NULL;
+    char *next = NULL;
+    if(value[0] !='0' || (value[1]|0x20)!='x') {
+        return NULL;
+    }
+    ptr = strtoll(value, &next, 16);
+    if (next == value) {
+        return NULL;
+    }
+    return ptr;
+}
